// --- PARAMETRI ---
float zoom = 10.0;  // <--- AUMENTATO DA 1.0 A 20.0 PER RIDURRE I BLOCCHI
float s = 512.0;    // Risoluzione virtuale

// --- LOGICA XOR ---
// Convertiamo u, v (0.0-1.0) in coordinate intere scalate
// Formula C++ originale: int xx = x * z / 5;
// Qui moltiplichiamo per zoom alto per avere il pattern fitto
int xx = int(u * s * zoom / 5.0);
int yy = int(v * s * zoom / 5.0);

// Formula XOR bitwise
int val = (xx ^ yy) % 256;

// Mappiamo a 0.0-1.0
float t = float(val) / 255.0;

// --- GENERAZIONE COLORE PSICHEDELICO (Inline) ---
// t * 3.0 serve a fare 3 giri completi di spettro
float time = t * 3.0; 
float freq = 6.283; // 2 * PI

// Calcolo componenti RGB con le fasi originali (0.00, 0.33, 0.67)
float r_psy = 0.5 + 0.5 * cos(freq * time + 0.00);
float g_psy = 0.5 + 0.5 * cos(freq * time + 0.33); 
float b_psy = 0.5 + 0.5 * cos(freq * time + 0.67); 

vec3 psyColor = vec3(r_psy, g_psy, b_psy);

// --- MIX FINALE ---
// Mischiamo il risultato psichedelico con la tinta base (Colore 1)
return (psyColor + u_col1) * 0.5;

